    for(float rad=0.0f;rad<radius+DELTA_NOTIONAL_ZERO;rad+=d_rad) {
        long n_thet=(long)(rad*2.0f+1.0f);
        for(long c1=0;c1<n_thet;++c1) {
            float thet=((float)c1/(float)n_thet)*TWO_PI;
