void CParticleProgram::ApplyTransform(const CMatrix3x4& transform)
{
    const CParticleSimulation& sim=PeekInitialSimulation();
    char* data=(char*)Constraints.PeekData();
    unsigned long total_length=Constraints.GetLength();
    unsigned long pos=0;
