   CMainGameComponent::Get()->GetPlayerManager().GetMainPlayer().GetPlayerHeroLogBook().AddEntry(LogBookNameTag[count],LogBookAbbreviatedNameTag[count],LogBookTextTag[count],LogBookCategory[count],false);
 }
}
