                        navigation->InterruptNavigation();
                        PhysicsTC->ResetPosition(position);
                        navigation->InterruptNavigation();
                        return true;
                    }
                }
                }
            }
        }
        CTCCreatureNavigation* navigation=0;
        if (HasTC(TCI_NAVIGATION))
            navigation=&static_cast<CTCCreatureNavigation&>(GetTC(TCI_NAVIGATION));
