                CTCFlashOnHit* effect=static_cast<CTCFlashOnHit*>(AddTC("CTCFlashOnHit",true,0));
                effect->SetFadeInTime(0);
                effect->SetFadeOutTime(0);
                effect->SetLifeTime(2);
